PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX prodi: <http://ld.company.org/prod-instances/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?result WHERE {
  ?expert a pv:SensorExpert ;
           rdfs:label ?result .
}

PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX prodi: <http://ld.company.org/prod-instances/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?result WHERE {
  ?lcd prodi:supplier ?supplier ;
        pv:hasType "LCD" .
  ?supplier rdfs:locatedIn ?city .
  FILTER(?city a pv:City ; pv:country "US") .
}

PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX prodi: <http://ld.company.org/prod-instances/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

ASK {
  ?service a pv:Service ;
           pv:appliesToBOM ?bom .
  ?bom pv:containsPart ?part .
  ?part pv:sourcedFrom "Russia" .
}

PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX prodi: <http://ld.company.org/prod-instances/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?supplierName ?country ?price WHERE {
  ?item a pv:HardwareItem ;
         pv:suppliedBy ?supplier .
  ?supplier rdfs:label ?supplierName ;
             pv:locatedIn ?country .
  ?item pv:cost ?price .
} ORDER BY DESC(?price) LIMIT 5 OFFSET 5

PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX prodi: <http://ld.company.org/prod-instances/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?product ?compatibleProduct (?priceDifference AS ?result) WHERE {
  ?product a pv:Product ;
           pv:compatibleWith ?compatibleProduct .
  ?product pv:price ?productPrice ;
            prodi:hasPriceHistory ?history .
  FILTER (EXISTS { ?history prodi:hasPrice ?price ; prodi:validFrom ?from . })
  BIND ((?productPrice - ?price) AS ?priceDifference)
}

PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX prodi: <http://ld.company.org/prod-instances/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?name ?email ?phone ?department ?directReport WHERE {
  ?employee a pv:Employee ;
             rdfs:label ?name ;
             pv:hasEmail ?email ;
             pv:hasPhoneNumber ?phone ;
             pv:worksIn ?department ;
             pv:reportsTo ?manager .
  OPTIONAL { ?manager pv:reportsTo ?directReport }
}

PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX prodi: <http://ld.company.org/prod-instances/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?result (AVG(?unitCost) AS ?averageUnitCost) WHERE {
  ?bom a pv:BillOfMaterials ;
       pv:containsHardwarePart ?part .
  ?part a pv:HardwarePart ;
         pv:unitCost ?unitCost .
} GROUP BY ?bom ORDER BY DESC(?averageUnitCost) LIMIT 1

PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX prodi: <http://ld.company.org/prod-instances/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?bom WHERE {
  ?bom a pv:BOM ;
        pv:containsPart ?part .
  ?part pv:supplier prodi:supplier-polish .
}
